function defaultCompare(sortKey) {
  return (a, b) => {
    const av = String(a[sortKey] || '');
    const bv = String(b[sortKey] || '');
    if (av && bv && av !== bv) return av.localeCompare(bv);
    if (av && !bv) return -1;
    if (!av && bv) return 1;
    return 0;
  };
}

function pickFairBySource(rows, options = {}) {
  const limit = Number(options.limit || rows.length || 0);
  const perSourceLimit = Number(options.perSourceLimit || limit || 1);
  const sourceKey = options.sourceKey || 'source_id';
  const fallbackKeys = options.fallbackKeys || [];
  const compare = options.compare || defaultCompare(options.sortKey || 'created_at');

  if (limit <= 0 || perSourceLimit <= 0) return [];

  const buckets = new Map();
  for (const row of rows || []) {
    const keyValues = [sourceKey, ...fallbackKeys].map((key) => row[key]).filter(Boolean);
    const source = String(keyValues[0] || '__unknown__');
    if (!buckets.has(source)) buckets.set(source, []);
    buckets.get(source).push(row);
  }

  const sourceOrder = [...buckets.keys()];
  for (const source of sourceOrder) {
    buckets.get(source).sort(compare);
  }

  const picked = [];
  const pickedBySource = {};
  let madeProgress = true;

  while (picked.length < limit && madeProgress) {
    madeProgress = false;
    for (const source of sourceOrder) {
      if (picked.length >= limit) break;
      pickedBySource[source] = pickedBySource[source] || 0;
      if (pickedBySource[source] >= perSourceLimit) continue;

      const bucket = buckets.get(source);
      if (!bucket || bucket.length === 0) continue;

      picked.push(bucket.shift());
      pickedBySource[source] += 1;
      madeProgress = true;
    }
  }

  return picked;
}

function pickFairByGroup(rows, options = {}) {
  const limit = Number(options.limit || (rows || []).length || 0);
  const perSourceLimit = Number(options.perSourceLimit || limit || 1);
  const groupKey = options.groupKey || 'niche';
  const groupFallbackKeys = options.groupFallbackKeys || [];
  const sourceKey = options.sourceKey || 'source_id';
  const sourceFallbackKeys = options.sourceFallbackKeys || [];
  const compare = options.compare || defaultCompare(options.sortKey || 'created_at');

  if (limit <= 0 || perSourceLimit <= 0) return [];

  const groups = new Map();
  for (const row of rows || []) {
    const groupValues = [groupKey, ...groupFallbackKeys].map((key) => row[key]).filter(Boolean);
    const sourceValues = [sourceKey, ...sourceFallbackKeys].map((key) => row[key]).filter(Boolean);
    const group = String(groupValues[0] || '__unknown_group__');
    const source = String(sourceValues[0] || '__unknown_source__');

    if (!groups.has(group)) {
      groups.set(group, {
        sourceOrder: [],
        buckets: new Map(),
        pickedBySource: {},
        nextSourceIndex: 0,
      });
    }
    const groupBucket = groups.get(group);
    if (!groupBucket.buckets.has(source)) {
      groupBucket.buckets.set(source, []);
      groupBucket.sourceOrder.push(source);
    }
    groupBucket.buckets.get(source).push(row);
  }

  const groupOrder = [...groups.keys()];
  for (const group of groupOrder) {
    const groupBucket = groups.get(group);
    for (const source of groupBucket.sourceOrder) {
      groupBucket.buckets.get(source).sort(compare);
    }
  }

  function pickFromGroup(groupBucket) {
    const totalSources = groupBucket.sourceOrder.length;
    if (totalSources === 0) return null;

    for (let attempts = 0; attempts < totalSources; attempts += 1) {
      const index = (groupBucket.nextSourceIndex + attempts) % totalSources;
      const source = groupBucket.sourceOrder[index];
      groupBucket.pickedBySource[source] = groupBucket.pickedBySource[source] || 0;
      if (groupBucket.pickedBySource[source] >= perSourceLimit) continue;

      const bucket = groupBucket.buckets.get(source);
      if (!bucket || bucket.length === 0) continue;

      groupBucket.nextSourceIndex = (index + 1) % totalSources;
      groupBucket.pickedBySource[source] += 1;
      return bucket.shift();
    }

    return null;
  }

  const picked = [];
  let madeProgress = true;
  while (picked.length < limit && madeProgress) {
    madeProgress = false;
    for (const group of groupOrder) {
      if (picked.length >= limit) break;
      const row = pickFromGroup(groups.get(group));
      if (!row) continue;
      picked.push(row);
      madeProgress = true;
    }
  }

  return picked;
}


function shellQuote(value) {
  return `'${String(value).replace(/'/g, `'\\''`)}'`;
}

function safeIdComponent(value) {
  const id = String(value || '').trim();
  if (!/^[A-Za-z0-9_-]+$/.test(id)) {
    throw new Error(`Unsafe id for yt-dlp path: ${JSON.stringify(value)}`);
  }
  return id;
}

function normalizeTimeRange(moment) {
  const start = Math.max(0, Math.floor(Number(moment.start_sec)));
  const end = Math.floor(Number(moment.end_sec));
  const duration = end - start;
  if (!Number.isFinite(start) || !Number.isFinite(end) || duration < 45 || duration > 90) {
    throw new Error(`Invalid yt-dlp clip range for ${moment.clip_moment_id || 'unknown'}: ${moment.start_sec}-${moment.end_sec}`);
  }
  return { start, end, duration };
}

function createdClipIdForMoment(moment) {
  return `CC-${safeIdComponent(moment.clip_moment_id)}`;
}

function ytdlpJobIdForMoment(moment) {
  return `YTDLP-${safeIdComponent(moment.clip_moment_id)}`;
}

function hasCreatedClip(moment, clips) {
  const createdId = createdClipIdForMoment(moment);
  const jobId = ytdlpJobIdForMoment(moment);
  return (clips || []).some((clip) => (
    String(clip.created_clip_id || '') === createdId ||
    String(clip.download_job_id || '') === jobId
  ));
}

function planYtDlpDownloads(moments, createdClips, folders = {}, options = {}) {
  const limit = Number(options.limit || 5);
  const perSourceLimit = Number(options.perSourceLimit || 1);
  const pending = [];

  for (const moment of moments || []) {
    if (String(moment.download_status || '') !== 'PENDING') continue;
    if (!moment.clip_moment_id || !moment.source_video_url) continue;

    let range;
    let createdClipId;
    let ytdlpJobId;
    try {
      range = normalizeTimeRange(moment);
      createdClipId = createdClipIdForMoment(moment);
      ytdlpJobId = ytdlpJobIdForMoment(moment);
    } catch {
      continue;
    }
    if (hasCreatedClip(moment, createdClips)) continue;

    const workdir = `/data/jobs/${createdClipId}`;
    pending.push({
      clip_moment_id: moment.clip_moment_id,
      created_clip_id: createdClipId,
      download_job_id: ytdlpJobId,
      video_id: moment.video_id,
      niche: moment.niche,
      source_id: moment.source_id || '',
      source_video_url: moment.source_video_url,
      start_sec: range.start,
      end_sec: range.end,
      duration_seconds: range.duration,
      clip_score: Number(moment.clip_score || 0),
      clip_title: moment.suggested_title || moment.core_idea || createdClipId,
      file_name: `${moment.niche}_${createdClipId}.mp4`,
      drive_folder_id: folders[moment.niche] || '',
      workdir,
      local_path: `${workdir}/source.mp4`,
      portrait_path: `${workdir}/portrait.mp4`,
      portrait_log_path: `${workdir}/ffmpeg-portrait.log`,
      log_path: `${workdir}/yt-dlp.log`,
      core_idea: moment.core_idea || '',
      suggested_title: moment.suggested_title || '',
      suggested_caption: moment.suggested_caption || '',
      reviewer_notes: [
        `provider=yt-dlp`,
        `strategy=${moment.strategy || ''}`,
        `clip_moment_id=${moment.clip_moment_id}`,
      ].join('; '),
      created_at: moment.created_at || '',
    });
  }

  return pickFairByGroup(pending, {
    limit,
    perSourceLimit,
    groupKey: 'niche',
    sourceKey: 'source_id',
    sourceFallbackKeys: ['niche'],
    compare: (a, b) => {
      const scoreDelta = Number(b.clip_score || 0) - Number(a.clip_score || 0);
      if (scoreDelta !== 0) return scoreDelta;
      return String(a.created_at || '').localeCompare(String(b.created_at || ''));
    },
  });
}

function buildYtDlpCommand(request) {
  safeIdComponent(request.created_clip_id);
  const range = normalizeTimeRange(request);
  const section = `*${range.start}-${range.end}`;
  return [
    'mkdir -p',
    shellQuote(request.workdir),
    '&&',
    'python3 -m yt_dlp',
    '--no-playlist',
    '--force-overwrites',
    '--download-sections',
    shellQuote(section),
    '--force-keyframes-at-cuts',
    '-f',
    shellQuote('bv*[ext=mp4]+ba[ext=m4a]/b[ext=mp4]/best'),
    '--merge-output-format',
    'mp4',
    '-o',
    shellQuote(`${request.workdir}/source.%(ext)s`),
    shellQuote(request.source_video_url),
    '>',
    shellQuote(request.log_path),
    '2>&1',
    '&&',
    'test -s',
    shellQuote(request.local_path),
    '&&',
    'ffprobe -v error -select_streams v:0 -show_entries stream=codec_type -of csv=p=0',
    shellQuote(request.local_path),
    '|',
    "grep -q '^video$'",
  ].join(' ');
}

function buildMomentStatus(request, status, extra = {}) {
  return {
    clip_moment_id: request.clip_moment_id,
    download_status: status,
    download_job_id: request.download_job_id || '',
    ...extra,
  };
}

function buildCreatedClipRow(request, drive, now = new Date().toISOString()) {
  return {
    created_clip_id: request.created_clip_id,
    download_job_id: request.download_job_id,
    video_id: request.video_id,
    niche: request.niche,
    clip_title: String(request.clip_title || ''),
    clip_url: '',
    local_file_name: request.file_name,
    google_drive_file_id: drive.id || '',
    google_drive_url: drive.webViewLink || (drive.id ? `https://drive.google.com/file/d/${drive.id}/view` : ''),
    duration_seconds: request.duration_seconds,
    transcript_excerpt: '',
    suggested_title: String(request.suggested_title || ''),
    suggested_caption: String(request.suggested_caption || ''),
    transformation_plan: '',
    review_status: 'AWAITING_DOWNLOAD',
    reviewer_notes: request.reviewer_notes || 'provider=yt-dlp',
    created_at: now,
  };
}

function buildPortraitCommand(request) {
  const inputPath = request.local_path;
  const outputPath = request.portrait_path;
  const logPath = request.portrait_log_path;
  const vf = 'scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920:(iw-1080)/2:(ih-1920)/2,setsar=1';
  return [
    'ffmpeg -y',
    '-i', shellQuote(inputPath),
    '-map 0:v:0',
    '-map 0:a:0?',
    '-vf', shellQuote(vf),
    '-c:v libx264 -preset veryfast -crf 23 -pix_fmt yuv420p',
    '-c:a aac -b:a 128k',
    '-movflags +faststart',
    shellQuote(outputPath),
    '>', shellQuote(logPath), '2>&1',
    '&&', 'test -s', shellQuote(outputPath),
    '&&',
    'ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=s=x:p=0',
    shellQuote(outputPath),
    '|',
    "grep -qx '1080x1920'",
  ].join(' ');
}


const requests = planYtDlpDownloads(
  $('Read Clip_Moments').all().map(i => i.json),
  $('Read Created_Clips').all().map(i => i.json),
  {
  CHRISTIAN_CONTENT: 'GOOGLE_DRIVE_FOLDER_CHRISTIAN_CONTENT',
  MOTIVATION_DISCIPLINE: 'GOOGLE_DRIVE_FOLDER_MOTIVATION_DISCIPLINE',
  FINANCE_BUSINESS: 'GOOGLE_DRIVE_FOLDER_FINANCE_BUSINESS',
  LIFE_VALUES_RELATIONSHIPS: 'GOOGLE_DRIVE_FOLDER_LIFE_VALUES_RELATIONSHIPS',
  AFRICAN_KENYAN_SUCCESS: 'GOOGLE_DRIVE_FOLDER_AFRICAN_KENYAN_SUCCESS',
},
  { limit: 5, perSourceLimit: 1 },
);
return requests.map((request, index) => ({ json: request, pairedItem: { item: index } }));

